useEffect(() => {
  // АВТО-ЛОГИН ПРИ ЗАПУСКЕ (БЕЗ БЭКЕНДА)
  const autoLogin = async () => {
    try {
      const response = await authAPI.getMe();
      setCurrentUser(response.data);
      setIsAuthenticated(true);
    } catch {
      setIsAuthenticated(false);
    } finally {
      setLoading(false);
    }
  };
  autoLogin();
}, []);
